import{_ as e,o as t,c as l,a2 as o}from"./chunks/framework.A5mep7Fe.js";const u=JSON.parse('{"title":"📈 05 · 大数据挖掘（推荐 / 搜索 / 广告 / 图挖掘）","description":"","frontmatter":{},"headers":[],"relativePath":"04-算法岗-传统深度学习/05-大数据挖掘.md","filePath":"04-算法岗-传统深度学习/05-大数据挖掘.md","lastUpdated":1786806808000}'),i={name:"04-算法岗-传统深度学习/05-大数据挖掘.md"};function r(s,a,n,d,p,h){return t(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="📈-05-·-大数据挖掘-推荐-搜索-广告-图挖掘" tabindex="-1">📈 05 · 大数据挖掘（推荐 / 搜索 / 广告 / 图挖掘） <a class="header-anchor" href="#📈-05-·-大数据挖掘-推荐-搜索-广告-图挖掘" aria-label="Permalink to &quot;📈 05 · 大数据挖掘（推荐 / 搜索 / 广告 / 图挖掘）&quot;">​</a></h1><blockquote><p>工业界算法岗的「硬通货」。推荐/搜索/广告是 AI 公司营收核心，岗位多、要求扎实的工程+算法。</p></blockquote><hr><h2 id="一、推荐系统经典架构" tabindex="-1">一、推荐系统经典架构 <a class="header-anchor" href="#一、推荐系统经典架构" aria-label="Permalink to &quot;一、推荐系统经典架构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>召回(百万→千) → 粗排(千→百) → 精排(百→十) → 重排(十→展示)</span></span></code></pre></div><ul><li><strong>召回</strong>：多路（协同/向量/热门），从全库快速缩小候选（双塔模型、ANN）</li><li><strong>精排</strong>：复杂模型（DeepFM / DIN / 树模型）精准打分</li><li><strong>重排</strong>：多样性、业务规则、去重</li></ul><h2 id="二、核心算法" tabindex="-1">二、核心算法 <a class="header-anchor" href="#二、核心算法" aria-label="Permalink to &quot;二、核心算法&quot;">​</a></h2><ul><li><strong>协同过滤</strong>：UserCF / ItemCF（基于行为相似）</li><li><strong>矩阵分解</strong>：隐向量建模</li><li><strong>深度学习</strong>：Wide&amp;Deep、DeepFM、DIN（用户兴趣）、DIEN</li><li><strong>向量召回</strong>：双塔 + 向量检索（Faiss）</li></ul><h2 id="三、特征工程-仍关键" tabindex="-1">三、特征工程（仍关键） <a class="header-anchor" href="#三、特征工程-仍关键" aria-label="Permalink to &quot;三、特征工程（仍关键）&quot;">​</a></h2><ul><li>类别特征（embedding）、数值特征（归一/分桶）、交叉特征</li><li>时序/行为序列特征、统计特征</li><li>特征重要性分析与清洗</li></ul><h2 id="四、评估与冷启动" tabindex="-1">四、评估与冷启动 <a class="header-anchor" href="#四、评估与冷启动" aria-label="Permalink to &quot;四、评估与冷启动&quot;">​</a></h2><ul><li>离线：AUC、GAUC、召回率</li><li>在线：CTR、CVR、时长、留存（AB 实验）</li><li>冷启动：内容/用户冷启动策略、探索利用（Bandit）</li></ul><h2 id="五、图挖掘" tabindex="-1">五、图挖掘 <a class="header-anchor" href="#五、图挖掘" aria-label="Permalink to &quot;五、图挖掘&quot;">​</a></h2><ul><li>图神经网络（GCN/GAT）、Node2Vec、社区发现</li><li>应用：社交推荐、风控关系网、知识图谱</li></ul><h2 id="六、高频追问" tabindex="-1">六、高频追问 <a class="header-anchor" href="#六、高频追问" aria-label="Permalink to &quot;六、高频追问&quot;">​</a></h2><p><strong>Q1：为什么需要多路召回而不是一个模型？</strong></p><blockquote><p>单模型难兼顾「全库覆盖+多兴趣」；多路互补（热门/协同/向量/实时）提升召回质量与覆盖，再靠精排择优。</p></blockquote><p><strong>Q2：Wide&amp;Deep 的 wide 和 deep 各解决什么？</strong></p><blockquote><p>Wide 记忆（历史高频共现），Deep 泛化（未知组合），结合兼顾记忆与泛化。</p></blockquote><p><strong>Q3：推荐系统怎么处理冷启动？</strong></p><blockquote><p>内容特征兜底、热度/探索策略、跨域迁移、Bandit 探索、用户注册信息利用。</p></blockquote><hr><p>➡️ 返回：<a href="./README">04-算法岗-传统深度学习 README</a> ｜ 进入：<a href="./../05-算法岗-前沿与具身/README">05-算法岗-前沿与具身</a></p>',23)])])}const b=e(i,[["render",r]]);export{u as __pageData,b as default};
